using BepInEx.Configuration;

namespace TooManyLagsDedicatedAddon
{
    internal sealed class Settings
    {
        internal readonly bool Enabled, Keep, Directional, IncludeOuter, RespectFireOwnership, StaticGrid, MobConeServerWhenMultiple, MobAttackForecast, MobOwnershipTest;
        internal readonly float CellSize, CheckInterval, InnerDelay, ForwardDelay, OuterDelay, FullDelay, OverlapHold;
        internal readonly float GraceMultiplier, MinimumGrace, FastMovementSpeed, RefillHold, MobConeRange, BossMobConeRange;
        internal readonly float MobTestInterval;
        internal readonly int AdaptivePing;
        internal readonly GridCoveragePattern Pattern;
        internal readonly Groups Groups;
        internal Settings(ConfigFile config)
        {
            const string scope = "Server only. Restart required. ";
            Enabled = config.Bind("00 - General", "Enabled", true, scope + "Enable this experimental addon; Dedicated Simulation must be active. Public chests, boats and idle carts use guarded grid ownership and native inventory opening. Editing and unsupported custom actions stay native.").Value;
            StaticGrid = config.Bind("00 - Simulation Settings", "UseGridForStaticBuildings", false, scope + "False keeps enabled eligible static building pieces on the server. True lets the normal grid share them with nearby players. Server-owned buildings can increase server CPU load. Does not add PUP collision support.").Value;
            Keep = config.Bind("01 - Grid", "KeepOwnershipOnCellExit", false, scope + "False returns managed objects outside player fields to server simulation. True retains vacated ownership. Nearby pickup owners/requesters stay protected; live fish retain native pickup priority. Native region releases remain unchanged. Both modes keep the full rear grid.").Value;
            CellSize = config.Bind("01 - Grid", "GridCellSizeMeters", 4f, new ConfigDescription(scope + "Cell size in metres. Four metres requires a rounded pattern.", new AcceptableValueList<float>(4f, 6.4f, 8f, 16f))).Value;
            Pattern = config.Bind("01 - Grid", "GridCoveragePattern", GridCoveragePattern.Rounded7x7, scope + "Player coverage shape.").Value;
            if (CellSize == 4f && Pattern == GridCoveragePattern.Square3x3) Pattern = GridCoveragePattern.Rounded5x5;
            CheckInterval = config.Bind("01 - Grid", "MovementRotationCheckIntervalSeconds", .1f, new ConfigDescription(scope + "Check character cell and direction. Unchanged coverage creates no field/object updates. No camera data is available from vanilla clients.", new AcceptableValueRange<float>(.05f, 5f))).Value;
            AdaptivePing = config.Bind("01 - Grid", "LargeGridPingThresholdMs", 200, new ConfigDescription(scope + "Directional mode: expand poor-connection coverage to four red rows (3/5/5/3 cells) plus three orange cells. Ping is cached for one second. Shrinks below 75% of this threshold to avoid jitter; unknown ping retains current size. Zero disables automatic expansion.", new AcceptableValueRange<int>(0, 5000))).Value;
            Directional = config.Bind("02 - Direction and Delays", "DirectionalGridMode", true, scope + "Use character direction for the forward row. The inner 3x3 includes rear cells. False uses the full selected pattern with one uniform timer.").Value;
            IncludeOuter = config.Bind("02 - Direction and Delays", "EnableOuterCells", false, scope + "Include yellow outer cells in directional mode. False keeps only the red 3x3 and, with rounded patterns, the orange forward row. Does not affect full-grid mode.").Value;
            FastMovementSpeed = config.Bind("02 - Direction and Delays", "FastMovementThresholdMetersPerSecond", 4f, new ConfigDescription(scope + "Horizontal native player speed at which orange cells use 0 seconds. Returns to the configured orange delay below 75% of this speed (default: below 3 m/s), preventing threshold jitter. Zero disables the speed override. No extra network messages.", new AcceptableValueRange<float>(0f, 30f))).Value;
            InnerDelay = Delay(config, "InnerTransitionDelaySeconds", 0f, "Red: the inner 3x3, including rear cells.");
            ForwardDelay = Delay(config, "ForwardTransitionDelaySeconds", .2f, "Orange: one extra forward row with rounded grids. Fast movement can override this delay to 0.");
            OuterDelay = Delay(config, "OuterTransitionDelaySeconds", 3f, "Yellow cells when enabled; also the grid retirement delay after a cell becomes empty.");
            FullDelay = Delay(config, "TransitionDelaySeconds", 2f, "Used only with the full grid.");
            OverlapHold = Delay(config, "ServerOverlapCooldownSeconds", 1f, "Hold after shared cells move to the server. Zero disables. Only new movement/direction requests can take them again.");
            GraceMultiplier = config.Bind("03 - Handoff Protection", "ClientToServerGracePingMultiplier", 2f, new ConfigDescription(scope + "Pending player-to-server transfers for direct-state interactions wait this many native round-trip times. Incoming source-object updates cancel that transfer. Does not delay server-to-player acquisition; cannot guarantee delivery deadlines.", new AcceptableValueRange<float>(0f, 10f))).Value;
            MinimumGrace = config.Bind("03 - Handoff Protection", "MinimumClientToServerGraceSeconds", .1f, new ConfigDescription(scope + "Minimum pending-transfer window. No extra window for native Pickable completion or purely local controls. Cancelled transfers require new grid activity. Zero disables this minimum.", new AcceptableValueRange<float>(0f, 5f))).Value;
            RefillHold = config.Bind("03 - Handoff Protection", "RefillOwnershipProtectionSeconds", 1f, new ConfigDescription(scope + "Reject automatic transfers after an observed fuel, material, cooking-slot or ammo increase. Repeated observed inserts restart this window. Expiry does not replay a transfer; fresh grid activity is required. Remote local actions are visible only after native replication. Zero disables this additional window.", new AcceptableValueRange<float>(0f, 10f))).Value;
            RespectFireOwnership = config.Bind("04 - Backend Compatibility", "RespectBackendFireOwnership", true, scope + "True keeps FireControl sources outside the grid. False lets enabled, eligible refill/fireplace objects use normal grid ownership and handoff protection; FireControl will not reclaim those objects. Other fires keep their backend policy. Server-only FireControl rules cannot be fully enforced on player-owned sources.").Value;
            MobConeRange = config.Bind("05 - Hostile Mobs", "HostileMobConeRangeMeters", 8f, new ConfigDescription(scope + "Cone distance for ordinary Hostile Mobs in overlapping player fields; bosses use BossMobConeRangeMeters. Cone width is 90 degrees (45 each side). Player selection follows the setting below; no eligible player means server ownership. Attack guards remain active; the mob's actual target is unchanged.", new AcceptableValueRange<float>(1f, 64f))).Value;
            BossMobConeRange = config.Bind("05 - Hostile Mobs", "BossMobConeRangeMeters", 10f, new ConfigDescription(scope + "Cone distance for creatures marked as bosses by Valheim's native IsBoss flag. Uses the same angle, player-selection rules and attack guards as ordinary Hostile Mobs.", new AcceptableValueRange<float>(1f, 64f))).Value;
            MobConeServerWhenMultiple = config.Bind("05 - Hostile Mobs", "ServerOwnedWhenMultiplePlayersInMobCone", true, scope + "In overlapping fields, use the server when more than one living, eligible player is in the mob's cone. One player gets ownership; none uses the server. False always selects the nearest eligible cone player. Existing attack guards still apply.").Value;
            MobAttackForecast = config.Bind("05 - Hostile Mobs", "EnableMobAttackForecast", true, scope + "Experimental additional handoff veto for player-owned Hostile Mobs. Native ability signals update cooldown timestamps; subtracts 0.1 seconds plus cached round-trip latency. Ready attacks use 5 degrees extra on each side and 0.5 metres extra range. Unknown/ambiguous abilities count as ready. Geometry runs only for a pending handoff after existing attack guards; blocked predictions wait for relevant events. No duplicate AI or client mod; observations are not an atomic safety guarantee.").Value;
            MobOwnershipTest = config.Bind("09 - Solo Mob Test", "EnableMobOwnershipTest", false, scope + "Diagnostic test, not normal gameplay. With exactly one online player, selects one nearby grid-covered Hostile Mob within 20 metres and alternates requests between player and server. All normal attack/forecast/readiness guards remain active. Waits for each successful handoff before reversing. Stops on death, unload, departure, a second accepted player or after five minutes. Writes test events to the server log. Disable and restart after testing.").Value;
            MobTestInterval = config.Bind("09 - Solo Mob Test", "MobOwnershipTestIntervalSeconds", 1f, new ConfigDescription(scope + "Minimum pause after a successful test handoff before requesting the opposite owner. Blocked requests wait for normal safeguards, without reversing or repeatedly issuing new requests. Only used when EnableMobOwnershipTest=true.", new AcceptableValueRange<float>(.1f, 10f))).Value;
            Groups = Groups.None;
            foreach (Groups group in new[] { Groups.Doors, Groups.Seats, Groups.Beds, Groups.Workstations, Groups.Wards, Groups.Pickables, Groups.Collectors, Groups.Feasts, Groups.MapTables, Groups.RefillStations, Groups.ArcheryTargets, Groups.LocalMarkers, Groups.TamedAnimals, Groups.LooseItems, Groups.Fish, Groups.StaticBuildings, Groups.Containers, Groups.Ships, Groups.Carts, Groups.HostileMobs })
                if (config.Bind("10 - Object Categories", group.ToString(), true, Description(group)).Value) Groups |= group;
        }
        private static string Description(Groups group)
        {
            if (group == Groups.Containers) return "Grid-manage public stationary chests. Nearby players acquire them automatically; shared or vacated fields use the server. Taking an available player's chest uses its native open-inventory check. Boat/cart cargo uses its own category; private chests, graves, incinerators and custom inventory controls stay native.";
            if (group == Groups.Ships) return "Grid-manage native boats at their helm position. A sole nearby player owns the boat; overlapping fields use the server, including while steering. Open cargo blocks handoffs, even outside helm coverage. Blocked overlaps retry on the existing two-second boat timer; settled boats do not query cargo again. Unsupported/custom boats keep native handling.";
            if (group == Groups.Carts) return "Grid-manage idle native carts. Native cargo and pulling checks block handoffs, including outside player fields. Remote hitch requests keep priority until observed attachment, native refusal or departure. Detaching resumes the grid; no extra cart polling timer. Unsupported carts keep native handling.";
            if (group == Groups.TamedAnimals) return "Grid-manage idle tamed animals. Riding, following, combat and transported animals keep native ownership. Wild creatures use the separate HostileMobs category; friendly magic summons stay excluded.";
            if (group == Groups.HostileMobs) return "Experimental grid ownership for untamed native MonsterAI/Humanoid creatures. Solo fields use that player; overlaps use the forward-cone rules in section 05. Transfers wait for attack completion. Remote attack observation is delayed and is not an atomic client acknowledgement. Friendly player summons and custom AI retain native handling.";
            if (group == Groups.LooseItems) return "Grid-manage eligible loose drops. Client owners and native pickup requesters keep priority while their grid footprints cover the item. Leaving releases failed pickup protection; exit retention and native handoff safeguards still apply.";
            if (group == Groups.Fish) return "Delegate eligible server-owned fish to nearby players. Native ownership, pickup grants and fishing retain priority until unload.";
            if (group == Groups.StaticBuildings) return "Manage eligible stationary, noninteractive Piece/WearNTear buildings. Server-owned by default; UseGridForStaticBuildings enables sharing.";
            return (group == Groups.Seats || group == Groups.Workstations || group == Groups.LocalMarkers) ? "Keep these purely local controls outside the grid, with a server default. Native player-local use remains unchanged." : "Manage this native interaction group. See shared safeguards under Enabled.";
        }
        private static float Delay(ConfigFile config, string key, float value, string description)
        { return config.Bind("02 - Direction and Delays", key, value, new ConfigDescription("Server only. Restart required. Seconds; 0 allowed. " + description, new AcceptableValueRange<float>(0f, 30f))).Value; }
    }
}
